const hoyStr = new Date().toISOString().slice(0, 10);

const reservas = $('Buscar Reservas Recientes de la Ventana Operativa').all()
  .filter(i => Object.keys(i.json).length > 0)
  .map(i => i.json);

const escalaciones = $('Buscar Escalaciones Recientes').all()
  .filter(i => Object.keys(i.json).length > 0)
  .map(i => i.json);

const reservasHoy = reservas.filter(b => String(b.createdAt || '').slice(0, 10) === hoyStr);
const confirmadasHoy = reservasHoy.filter(b => b.status === 'confirmada');
const pendientesHoy = reservasHoy.filter(b => b.status === 'pendiente_pago');
const ingresoHoy = confirmadasHoy.reduce((sum, b) => sum + (Number(b.totalUSD) || 0), 0);

// KPI de Tasa de Conversión
const totalIntentosHoy = confirmadasHoy.length + pendientesHoy.length;
const tasaConversion = totalIntentosHoy > 0 ? ((confirmadasHoy.length / totalIntentosHoy) * 100).toFixed(1) : '0.0';

const manana = new Date(); manana.setDate(manana.getDate() + 1);
const mananaStr = manana.toISOString().slice(0, 10);
const toursDeManana = reservas.filter(b => b.status === 'confirmada' && String(b.date || '').slice(0, 10) === mananaStr);

const escalacionesHoy = escalaciones.filter(e => String(e.createdAt || '').slice(0, 10) === hoyStr);
const escalacionesTotalAbiertas = escalaciones.length;

const LF = String.fromCharCode(10);
const mensaje = [
  '📊 Reporte Diario Operativo — Costa Rica Tours',
  `Fecha: ${hoyStr} (8:00 PM CR)`,
  '',
  `• Reservas confirmadas hoy: ${confirmadasHoy.length}`,
  `• Reservas pendientes de pago hoy: ${pendientesHoy.length}`,
  `• Tasa de conversión de hoy: ${tasaConversion}% (${confirmadasHoy.length}/${totalIntentosHoy})`,
  `• Ingresos confirmados hoy: $${ingresoHoy.toFixed(2)} USD`,
  `• Tours programados para mañana: ${toursDeManana.length}`,
  '',
  `⚠️ Escalaciones nuevas hoy: ${escalacionesHoy.length}`,
  `⚠️ Escalaciones en ventana operativa: ${escalacionesTotalAbiertas}`,
  '',
  '🟢 Sistema n8n y plataforma operando con normalidad.'
].join(LF);

return [{ json: { mensaje, confirmadasHoy: confirmadasHoy.length, pendientesHoy: pendientesHoy.length, tasaConversion, ingresoHoy, escalacionesHoy: escalacionesHoy.length } }];
